when.condition:
@{
        var url = context.Request.OriginalUrl;
        var range = context.Request.Headers.GetValueOrDefault("Range", "");
        return context.Request.Method != "GET" ||
          url.Scheme != "https" ||
          url.Host != "__VIEWER_HOST__" ||
          url.Port != 443 ||
          !string.IsNullOrEmpty(url.QueryString) ||
          (context.Request.Headers.ContainsKey("Range") && !Regex.IsMatch(range, @"\Abytes=[0-9]+-[0-9]+\z")) ||
          context.Request.Headers.Keys.Any(name => name.StartsWith("x-ms-", StringComparison.OrdinalIgnoreCase));
      }

set-variable.value:
@{
      var viewer = (Jwt)context.Variables["crab-viewer"];
      var source = Encoding.UTF8.GetString(Convert.FromBase64String("__REPOSITORY_PREFIX_BASE64__"));
      var suffix = Encoding.UTF8.GetString(Convert.FromBase64String("__PROTECTED_VIEW_SUFFIX_BASE64__"));
      var repository = source + suffix;
      var path = context.Request.OriginalUrl.Path;
      if (viewer.Algorithm != "RS256" ||
          viewer.Subject != repository ||
          !Regex.IsMatch(source, @"\A[A-Za-z0-9._-]+(?:/[A-Za-z0-9._-]+)*\z") ||
          source.Split("/".ToCharArray()).Any(segment => segment == "." || segment == "..") ||
          (suffix.Length != 0 && !Regex.IsMatch(suffix, @"\A/acl-views/v2/[a-f0-9]{64}/(?:0|[1-9][0-9]{0,19})-[a-f0-9]{64}\z")) ||
          !path.StartsWith("/crab/" + repository + "/", StringComparison.Ordinal)) {
        return "";
      }
      var key = path.Substring(7 + repository.Length);
      var git = Regex.Match(key, @"\A(?:(?<kind>v2/(?:capsules|checkpoints|catalogs|pack-layers))/|(?<kind>v2/history)/(?:source-roots/)?)(?<fanout>[a-f0-9]{2})/\k<fanout>[a-f0-9]{62}\z");
      var lfs = Regex.Match(key, @"\A(?<kind>lfs/objects)/(?<first>[a-f0-9]{2})/(?<second>[a-f0-9]{2})/\k<first>\k<second>[a-f0-9]{60}\z");
      var xet = Regex.Match(key, @"\A(?<kind>\.crab/(?:xorbs|shards|capsule-chunk-pages))/(?<fanout>[a-f0-9]{2})/\k<fanout>[a-f0-9]{62}\z");
      var kind = git.Success ? git.Groups["kind"].Value : lfs.Success ? lfs.Groups["kind"].Value :
          (suffix.Length != 0 && xet.Success ? xet.Groups["kind"].Value : "");
      if (kind.Length == 0 ||
          !viewer.Claims.ContainsKey("prefix") ||
          viewer.Claims["prefix"].Length != 1 ||
          viewer.Claims["prefix"][0] != repository + "/" + kind + "/") {
        return "";
      }
      return "/" + repository + "/" + key;
    }
